// Acceptance trace: T-AC-03, T-AC-05, T-AC-07 (test names use Rust-compatible t_ac_ identifiers).
//! @generated by:gauntlet run:muxtop-exec-pty
//! Real Bollard HTTP/upgrade requests against a deterministic local daemon.

use futures::StreamExt;
use muxtop_core::container_exec::ExecSize;
use muxtop_core::{ConnectionTarget, ContainerEngine, DockerEngine, EngineError};
use serde_json::{Value, json};
use std::sync::{Arc, Mutex};
use std::time::Duration;
use tokio::io::{AsyncRead, AsyncReadExt, AsyncWrite, AsyncWriteExt};
use tokio::net::TcpListener;
use tokio::task::{JoinHandle, JoinSet};

const FULL_ID: &str = "abcdef012345abcdef012345abcdef012345abcdef012345abcdef012345abcdef";
const TEST_DEADLINE: Duration = Duration::from_secs(5);

#[derive(Debug)]
struct Request {
    path: String,
    body: Value,
}

struct Daemon {
    target: ConnectionTarget,
    requests: Arc<Mutex<Vec<Request>>>,
    task: JoinHandle<()>,
}

impl Drop for Daemon {
    fn drop(&mut self) {
        self.task.abort();
    }
}

impl Daemon {
    async fn start(failure: Option<(&'static str, u16)>, running: bool) -> Self {
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let target = ConnectionTarget::Http(format!("http://{}", listener.local_addr().unwrap()));
        let requests = Arc::new(Mutex::new(Vec::new()));
        let captured = requests.clone();
        let task = tokio::spawn(async move {
            let mut connections = JoinSet::new();
            loop {
                tokio::select! {
                    accepted = listener.accept() => {
                        let (stream, _) = accepted.unwrap();
                        let captured = captured.clone();
                        connections.spawn(async move {
                            serve(stream, captured, failure, running).await;
                        });
                    }
                    Some(result) = connections.join_next() => { result.unwrap(); }
                }
            }
        });
        Self {
            target,
            requests,
            task,
        }
    }

    fn bodies_for(&self, suffix: &str) -> Vec<Value> {
        self.requests
            .lock()
            .unwrap()
            .iter()
            .filter(|request| request.path.ends_with(suffix))
            .map(|request| request.body.clone())
            .collect()
    }
}

async fn read_request(stream: &mut (impl AsyncRead + Unpin)) -> Request {
    let mut bytes = Vec::new();
    let end = loop {
        let byte = stream.read_u8().await.unwrap();
        bytes.push(byte);
        assert!(bytes.len() < 16384);
        if bytes.ends_with(b"\r\n\r\n") {
            break bytes.len();
        }
    };
    let header = String::from_utf8(bytes).unwrap();
    let path = header
        .lines()
        .next()
        .unwrap()
        .split_whitespace()
        .nth(1)
        .unwrap()
        .to_string();
    let length: usize = header
        .lines()
        .find_map(|line| {
            let (name, value) = line.split_once(':')?;
            name.eq_ignore_ascii_case("content-length")
                .then(|| value.trim().parse().unwrap())
        })
        .unwrap_or(0);
    assert!(end + length < 32768);
    let mut body = vec![0; length];
    stream.read_exact(&mut body).await.unwrap();
    Request {
        path,
        body: if body.is_empty() {
            Value::Null
        } else {
            serde_json::from_slice(&body).unwrap()
        },
    }
}

async fn reply(stream: &mut (impl AsyncWrite + Unpin), status: u16, body: Value) {
    let body = body.to_string();
    let header = format!(
        "HTTP/1.1 {status} Result\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
        body.len()
    );
    stream.write_all(header.as_bytes()).await.unwrap();
    stream.write_all(body.as_bytes()).await.unwrap();
}

async fn serve(
    mut stream: impl AsyncRead + AsyncWrite + Unpin,
    requests: Arc<Mutex<Vec<Request>>>,
    failure: Option<(&str, u16)>,
    running: bool,
) {
    let request = read_request(&mut stream).await;
    let path = request.path.clone();
    requests.lock().unwrap().push(request);
    if path.starts_with("/v") {
        reply(
            &mut stream,
            400,
            json!({"message":"client API version is too new"}),
        )
        .await;
    } else if let Some((suffix, code)) = failure
        && path.ends_with(suffix)
    {
        reply(
            &mut stream,
            code,
            json!({"message": "exec refused by test daemon"}),
        )
        .await;
    } else if path.ends_with("/info") {
        reply(
            &mut stream,
            200,
            json!({"ServerVersion":"27.0", "OperatingSystem":"Docker"}),
        )
        .await;
    } else if path.ends_with("/exec") {
        reply(&mut stream, 201, json!({"Id":"test-exec-id"})).await;
    } else if path.ends_with("/start") {
        stream
            .write_all(
                b"HTTP/1.1 101 UPGRADED\r\nConnection: Upgrade\r\nUpgrade: tcp\r\n\r\nprompt> ",
            )
            .await
            .unwrap();
        let mut buffer = [0; 4096];
        loop {
            let length = stream.read(&mut buffer).await.unwrap();
            if length == 0 || &buffer[..length] == b"exit\r" {
                break;
            }
            if stream.write_all(&buffer[..length]).await.is_err() {
                break;
            }
        }
    } else if path.contains("/resize?") {
        reply(&mut stream, 200, Value::Null).await;
    } else if path.ends_with("/json") {
        reply(&mut stream, 200, json!({"Running":running, "ExitCode":42})).await;
    } else {
        panic!("unexpected daemon request: {path}");
    }
}

#[tokio::test]
async fn t_ac_03_05_07_actual_bollard_pty_round_trip_resize_and_exit() {
    tokio::time::timeout(TEST_DEADLINE, async {
        let daemon = Daemon::start(None, false).await;
        let engine = DockerEngine::connect_explicit(daemon.target.clone())
            .await
            .unwrap();
        let mut session = engine
            .exec_shell(
                FULL_ID,
                ExecSize {
                    columns: 93,
                    rows: 41,
                },
            )
            .await
            .unwrap();
        assert_eq!(session.output.next().await.unwrap().unwrap(), b"prompt> ");
        let bytes = b"hello\x03\x04\x1b[A\xc3\xa9\r\n";
        session.input.write_all(bytes).await.unwrap();
        let mut echoed = Vec::new();
        while echoed.len() < bytes.len() {
            echoed.extend(session.output.next().await.unwrap().unwrap());
        }
        assert_eq!(echoed, bytes);
        // TTY output has no Docker log headers: in particular a leading NUL
        // must not be parsed as one. Exercise every byte, including 0x00..0x02.
        let binary: Vec<u8> = (0..=255).collect();
        session.input.write_all(&binary).await.unwrap();
        let mut echoed = Vec::new();
        while echoed.len() < binary.len() {
            echoed.extend(session.output.next().await.unwrap().unwrap());
        }
        assert_eq!(echoed, binary);
        session
            .control
            .resize(ExecSize {
                columns: 131,
                rows: 57,
            })
            .await
            .unwrap();
        session.input.write_all(b"exit\r").await.unwrap();
        assert!(session.output.next().await.is_none());
        assert_eq!(session.control.exit_code().await.unwrap(), Some(42));

        let create = daemon.bodies_for("/exec");
        assert_eq!(create.len(), 1);
        assert_eq!(create[0]["Cmd"], json!(["/bin/sh"]));
        for key in ["Tty", "AttachStdin", "AttachStdout", "AttachStderr"] {
            assert_eq!(create[0][key], true);
        }
        assert_eq!(create[0]["ConsoleSize"], json!([41, 93]));
        for key in ["User", "Privileged", "WorkingDir"] {
            assert!(create[0].get(key).is_none());
        }
        assert!(create[0]["Env"][0].as_str().unwrap().starts_with("TERM="));
        assert_eq!(daemon.bodies_for("/start")[0]["Tty"], true);
        let requests = daemon.requests.lock().unwrap();
        assert!(
            requests
                .iter()
                .any(|request| request.path == "/exec/test-exec-id/start"),
            "raw exec must use the same unversioned routes as the Bollard client"
        );
        assert!(requests.iter().any(|request| {
            request
                .path
                .ends_with(&format!("/containers/{FULL_ID}/exec"))
        }));
        assert!(requests.iter().any(
            |request| request.path.contains("/exec/test-exec-id/resize?")
                && request.path.contains("w=131")
                && request.path.contains("h=57")
        ));
    })
    .await
    .expect("PTY test timed out");
}

#[tokio::test]
async fn t_ac_03_daemon_refusal_is_not_retried_or_hidden() {
    for (endpoint, status) in [
        ("/exec", 403),
        ("/exec", 404),
        ("/exec", 409),
        ("/start", 500),
    ] {
        tokio::time::timeout(TEST_DEADLINE, async {
            let daemon = Daemon::start(Some((endpoint, status)), false).await;
            let engine = DockerEngine::connect_explicit(daemon.target.clone())
                .await
                .unwrap();
            let error = engine
                .exec_shell(
                    FULL_ID,
                    ExecSize {
                        columns: 80,
                        rows: 24,
                    },
                )
                .await
                .err()
                .unwrap();
            match status {
                403 => assert!(matches!(error, EngineError::PermissionDenied(_))),
                404 => assert!(matches!(error, EngineError::ContainerNotFound(_))),
                _ => assert!(error.to_string().contains("exec refused")),
            }
            assert_eq!(
                daemon.bodies_for(endpoint).len(),
                1,
                "never start another shell automatically"
            );
        })
        .await
        .unwrap();
    }
}

#[tokio::test]
async fn t_ac_07_running_exec_does_not_claim_a_successful_exit() {
    tokio::time::timeout(TEST_DEADLINE, async {
        let daemon = Daemon::start(None, true).await;
        let engine = DockerEngine::connect_explicit(daemon.target.clone())
            .await
            .unwrap();
        let session = engine
            .exec_shell(
                FULL_ID,
                ExecSize {
                    columns: 0,
                    rows: 0,
                },
            )
            .await
            .unwrap();
        assert_eq!(session.control.exit_code().await.unwrap(), None);
        assert_eq!(daemon.bodies_for("/exec")[0]["ConsoleSize"], json!([1, 1]));
    })
    .await
    .unwrap();
}

#[cfg(unix)]
#[tokio::test]
async fn t_ac_03_unix_socket_attachment_preserves_leading_nul() {
    tokio::time::timeout(TEST_DEADLINE, async {
        let directory = tempfile::tempdir().unwrap();
        let path = directory.path().join("engine.sock");
        let listener = tokio::net::UnixListener::bind(&path).unwrap();
        let requests = Arc::new(Mutex::new(Vec::new()));
        let captured = requests.clone();
        let task = tokio::spawn(async move {
            let mut connections = JoinSet::new();
            loop {
                tokio::select! {
                    accepted = listener.accept() => {
                        let (stream, _) = accepted.unwrap();
                        let captured = captured.clone();
                        connections.spawn(async move { serve(stream, captured, None, false).await; });
                    }
                    Some(result) = connections.join_next() => { result.unwrap(); }
                }
            }
        });
        let daemon = Daemon { target: ConnectionTarget::Unix(path), requests, task };
        let engine = DockerEngine::connect_explicit(daemon.target.clone()).await.unwrap();
        let mut session = engine.exec_shell(FULL_ID, ExecSize { columns:80, rows:24 }).await.unwrap();
        assert_eq!(session.output.next().await.unwrap().unwrap(), b"prompt> ");
        session.input.write_all(b"\x00\x01\x02").await.unwrap();
        let mut bytes = Vec::new();
        while bytes.len() < 3 { bytes.extend(session.output.next().await.unwrap().unwrap()); }
        assert_eq!(bytes, b"\x00\x01\x02");
        drop(session);
    }).await.expect("Unix exec attachment did not finish");
}
